import threading
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.data = OrderedDict()
        self._lock = threading.Lock()
    def get(self, key):
        with self._lock:
            if key not in self.data:
                return -1
            self.data.move_to_end(key)
            return self.data[key]
    def put(self, key, value):
        with self._lock:
            if key in self.data:
                self.data.move_to_end(key)
            self.data[key] = value
            if len(self.data) > self.cap:
                self.data.popitem(last=False)
```
A single `threading.Lock` makes read-modify-write atomic. For higher read throughput, consider `threading.RLock` or a sharded cache.

