class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node['$'] = True
    def words_with_prefix(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        out = []
        def walk(n, path):
            if n.get('$'):
                out.append(path)
            for ch, child in n.items():
                if ch != '$':
                    walk(child, path + ch)
        walk(node, prefix)
        return out
```
