def num_islands(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    count = 0
    def dfs(r, c):
        if 0 <= r < R and 0 <= c < C and g[r][c] == 1:
            g[r][c] = 0
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
    for r in range(R):
        for c in range(C):
            if g[r][c] == 1:
                count += 1
                dfs(r, c)
    return count
```
DFS sinks each island by zeroing its cells, so every land cell is visited once — total O(R*C).

