def encode(s: str) -> str:
    if not s:
        return ''
    out = []
    prev, count = s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{prev}{count}")
            prev, count = ch, 1
    out.append(f"{prev}{count}")
    return ''.join(out)

def decode(s: str) -> str:
    out, i = [], 0
    while i < len(s):
        ch = s[i]
        j = i + 1
        while j < len(s) and s[j].isdigit():
            j += 1
        out.append(ch * int(s[i+1:j]))
        i = j
    return ''.join(out)
```
Both passes are linear. The decoder assumes a single character followed by its run count.

